a = {"id": "r1", "title": "A", "n": 1}
b = {"id": "r1", "title": "B", "n": 1, "extra": True}
for k in sorted(set(a) | set(b)):
    if k not in a: print("+ %s = %r" % (k, b[k]))
    elif k not in b: print("- %s was %r" % (k, a[k]))
    elif a[k] != b[k]: print("~ %s: %r -> %r" % (k, a[k], b[k]))

