vals = [10, 12, 11, 13, 12, 200, 11, 12]
s = sorted(vals)
def pct(v): return 100.0 * s.index(v) / (len(s) - 1)
for v in sorted(set(vals)):
    print("value %3d at percentile %5.1f" % (v, pct(v)))

